<?php
namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class StoreProductRequest extends FormRequest { public function authorize():bool{return $this->user()?->role==='vendor';} public function rules():array{return ['category_id'=>['required','exists:categories,id'],'name'=>['required','string','max:160'],'description'=>['required','string','max:5000'],'sku'=>['required','string','max:80',Rule::unique('products','sku')],'price'=>['required','numeric','min:0.01'],'quantity'=>['required','integer','min:0'],'images.*'=>['nullable','image','mimes:jpg,jpeg,png,webp','max:5120']];} }
